// C002-T-031 — the Copilot target package (C002-IF-005 §3) on fx-dist: `dist/copilot/` generated by the
// generator into a temporary folder, in both enforcement modes, and read back from disk. Expected values
// come from the mapping table and the source plugin, never from a copy (C002-CAP-01 acceptance,
// verification note).
//   C002-TC-301 (C002-TS-301)  package layout: agents, install/plugin.json, prompt files, skills, install/mcp.json,
//                              no plugin.json/.mcp.json/hooks.json at the root, the CLI copy's SHA-256
//   C002-TC-302 (C002-TS-302)  fx-dist-bad: a required file removed is reported naming it (TGT-LAYOUT-001)
//   C002-TC-305 (C002-TS-305)  every prompt file bound to the conductor, no guard line
//   C002-TC-306 (C002-TS-306)  install notes
//   C002-TC-308 (C002-TS-308)  server mode: every agent has a tools list, none grants a generic edit or terminal tool
//   C002-TC-310 (C002-TS-310)  both modes: sdd-files and sdd-shell in install/mcp.json only
//   C002-TC-327 (C002-TS-327)  fx-dist-bad: a server profile removed, or declared in a root .mcp.json (TGT-MCP-001)
//   C002-TC-328 (C002-TS-328)  prompt file names `<name>.prompt.md`
//   C002-TC-339 (C002-TS-339)  hooks fallback: the conductor and every prompt file hold the server profiles
//   C002-TC-124 (C002-TS-124)  the Copilot row: the serena entry of install/mcp.json
// The `install/hooks.template.json` and `hooks/tool-classes.json` clauses of C002-TC-301 and their rows
// of C002-TC-302 came with C002-T-033 (also in package-hooks.test.ts). Carried: the TGT-GRANT-001 clause of C002-TC-339 to C002-T-035;
// C002-TC-306 timing to C002-T-057; C002-TC-309 and C002-TC-329 (manual VS Code) to C002-T-050.
import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { copilotPackageFindings, emitCopilot, INSTALL_SOURCE, ROOT_FORBIDDEN } from "../../../scripts/generate/emit/copilot.ts";
import { declaredServers } from "../../../scripts/generate/emit/opencode.ts";
import { main } from "../../../scripts/generate/main.ts";
import { readSource } from "../../../scripts/generate/reader.ts";
import { loadTargetTable, TARGETS, type MappingTable, type Mode } from "../../../scripts/generate/tables.ts";
import { CONDUCTOR, listField, translateAgents } from "../../../scripts/generate/translate/frontmatter.ts";
import { skillHeading } from "../../../scripts/generate/translate/inline.ts";
import { MANIFEST } from "../../../scripts/generate/writer.ts";
import { splitFrontmatter } from "../../../src/model/frontmatter.ts";
import { repoRoot } from "../../helpers.ts";

const root = repoRoot();
const PLUGIN = join(root, "plugins", "architect");
const read = readSource(PLUGIN);
assert.deepEqual(read.diagnostics, [], "the source plugin reads without diagnostics");
const source = read.source;
const table: MappingTable = loadTargetTable(root, "copilot");
const peers = TARGETS.map((t) => loadTargetTable(root, t));
const MODES: Mode[] = ["sdd-mcp-server", "copilot-hooks"];
const agentNames = source.agents.map((a) => a.name).sort();
const commandNames = source.commands.map((c) => c.name).sort();
const specialists = source.agents.map((a) => a.name).filter((n) => n !== CONDUCTOR);
const AGENTS_DIR = table.placement["agents_dir"]!;
const PROMPTS_DIR = table.placement["commands_dir"]!;
const SKILLS_DIR = table.placement["skills_dir"]!;
const CONFIG = table.placement["config_file"]!;
const PLUGIN_MANIFEST = table.placement["plugin_manifest"]!;
const CLI_COPY = table.placement["cli_copy"]!;
const INSTALL = table.placement["install_notes"]!;
const sha = (data: Buffer) => createHash("sha256").update(data).digest("hex");

/**
 * Generic edit and terminal tools of VS Code, by name or as a tool set that holds one: the table's own
 * hooks-fallback mapping of Write, Edit and Bash, and the other built-in names and sets.
 */
const hooksGrants = (tool: string) => {
  const e = table.tools[tool];
  return e && !Array.isArray(e) ? (e.by_mode["copilot-hooks"] ?? []) : [];
};
const GENERIC = new Set([...hooksGrants("Write"), ...hooksGrants("Edit"), ...hooksGrants("Bash"), "edit", "execute", "editFiles", "createFile", "runCommands", "runInTerminal", "terminal", "runTasks", "new", "vscode"]);

/** Every file under `dir` (relative, `/`-separated) with its bytes. */
function readTree(dir: string): Map<string, Buffer> {
  const out = new Map<string, Buffer>();
  const walk = (abs: string, rel: string) => {
    for (const name of readdirSync(abs).sort()) {
      const p = join(abs, name);
      const r = rel === "" ? name : `${rel}/${name}`;
      if (statSync(p).isDirectory()) walk(p, r);
      else out.set(r, readFileSync(p));
    }
  };
  walk(dir, "");
  return out;
}

/** fx-dist: the Copilot package generated for `mode`, read back from disk (built once per mode). */
const packages = new Map<Mode, Map<string, Buffer>>();
function fxDist(mode: Mode): Map<string, Buffer> {
  const hit = packages.get(mode);
  if (hit) return hit;
  const base = mkdtempSync(join(tmpdir(), "sdd-fx-dist-cp-"));
  try {
    const err: string[] = [];
    const code = main(["--target", "copilot", "--mode", `copilot=${mode}`, "--out", join(base, "dist"), "--quiet"], { cwd: root, stdout: () => {}, stderr: (l) => err.push(l) });
    assert.equal(code, 0, err.join("\n"));
    const files = readTree(join(base, "dist", "copilot"));
    packages.set(mode, files);
    return files;
  } finally {
    rmSync(base, { recursive: true, force: true });
  }
}

const text = (files: Map<string, Buffer>, p: string) => {
  const b = files.get(p);
  assert.ok(b, `${p} exists`);
  return b.toString("utf8");
};
const front = (t: string) => {
  const d = splitFrontmatter(t);
  assert.ok(d.data, "the file has a frontmatter mapping");
  return { data: d.data, body: d.lines.slice(d.bodyStartLine - 1).join("\n") };
};
type Server = { type: string; url?: string; command?: string; args?: string[] };
const mcp = (files: Map<string, Buffer>) => JSON.parse(text(files, CONFIG)) as { servers: Record<string, Server> };
const inDir = (files: Map<string, Buffer>, dir: string) => [...files.keys()].filter((p) => p.startsWith(`${dir}/`)).map((p) => p.slice(dir.length + 1));
const emitInput = (mode: Mode) => ({ source, table, target: "copilot" as const, mode, peers });
const agentFile = (name: string) => `${AGENTS_DIR}/${name}.agent.md`;
const promptFile = (name: string) => `${PROMPTS_DIR}/${name}.prompt.md`;
const toolsOf = (files: Map<string, Buffer>, p: string) => {
  const tools = front(text(files, p)).data["tools"];
  assert.ok(Array.isArray(tools), `${p}: has a tools list`);
  return tools as string[];
};

for (const mode of MODES) {
  test(`C002-TC-301 (C002-TS-301) [${mode}]: agents, install/plugin.json, prompt files, skills, install/mcp.json and the CLI copy; nothing at the root that makes a plugin`, () => {
    const files = fxDist(mode);
    assert.equal(agentNames.length, 10);
    assert.equal(commandNames.length, 13);
    assert.deepEqual(inDir(files, AGENTS_DIR).sort(), agentNames.map((n) => `${n}.agent.md`));
    for (const n of ["sdd-conductor", "sdd-auditor"]) assert.ok(files.has(agentFile(n)), n);
    const manifest = JSON.parse(text(files, PLUGIN_MANIFEST)) as Record<string, unknown>;
    assert.equal(PLUGIN_MANIFEST, "install/plugin.json");
    assert.equal(manifest["name"], "architect");
    assert.equal(manifest["commands"], PROMPTS_DIR);
    assert.equal(manifest["version"], (JSON.parse(readFileSync(join(PLUGIN, ".claude-plugin", "plugin.json"), "utf8")) as { version: string }).version);
    assert.equal(typeof manifest["description"], "string");
    assert.deepEqual(inDir(files, PROMPTS_DIR).sort(), commandNames.map((n) => `${n}.prompt.md`).sort());
    for (const s of source.skills) {
      const { data } = front(text(files, `${SKILLS_DIR}/${s.name}/SKILL.md`));
      assert.equal(data["name"], s.name, `${s.name}: Agent Skills name = folder name`);
      assert.ok(typeof data["description"] === "string" && data["description"] !== "", `${s.name}: description`);
      for (const r of s.resources) assert.ok(files.has(`${SKILLS_DIR}/${r.path.slice("skills/".length)}`), r.path);
    }
    assert.deepEqual(new Set(inDir(files, SKILLS_DIR).map((p) => p.split("/")[0])), new Set(source.skills.map((s) => s.name)));
    assert.deepEqual(Object.keys(mcp(files).servers).sort(), ["context7", "deepwiki", "sdd-files", "sdd-shell", "serena"]);
    assert.deepEqual(Object.keys(mcp(files).servers).sort(), declaredServers(table, mode));
    for (const p of ROOT_FORBIDDEN) assert.ok(!files.has(p), `no ${p} at the package root`);
    assert.equal(CLI_COPY, "scripts/sdd.mjs");
    assert.equal(sha(files.get(CLI_COPY)!), sha(readFileSync(join(PLUGIN, "scripts", "sdd.mjs"))), "the CLI copy has the SHA-256 of the plugin's bundle");
    assert.ok(files.has(MANIFEST) && files.has(INSTALL));
    assert.deepEqual(copilotPackageFindings(files, emitInput(mode)), [], "the target structure findings of a clean package");
    const skillFiles = source.skills.reduce((n, s) => n + 1 + s.resources.length, 0);
    assert.ok(files.has(table.placement["hooks_file"]!) && files.has("hooks/tool-classes.json"), "the hook template and the tool classes file (C002-T-033)");
    assert.equal(files.size, 10 + 13 + skillFiles + 7, "nothing else (plugin manifest, MCP configuration, hook template, tool classes, CLI copy, install notes, generation manifest)");
  });

  test(`agent frontmatter [${mode}]: name = file name, model of the tier, a tools list, agents, user-invocable false on the nine specialists, no memory or hooks`, () => {
    const files = fxDist(mode);
    const derived = translateAgents(emitInput(mode));
    assert.deepEqual(derived.diagnostics, []);
    for (const a of derived.agents) {
      const fm = a.frontmatter;
      const { data } = front(text(files, agentFile(fm.name)));
      assert.deepEqual(Object.keys(data), fm.name === CONDUCTOR ? ["name", "description", "model", "tools", "agents"] : ["name", "description", "model", "tools", "agents", "user-invocable"], fm.name);
      assert.equal(data["name"], fm.name);
      assert.equal(data["model"], table.models[fm.tier]);
      assert.deepEqual(data["tools"], fm.tools, `${fm.name}: the tools the table derives`);
      if (fm.name === CONDUCTOR) {
        assert.deepEqual([...(data["agents"] as string[])].sort(), [...specialists].sort(), "the conductor starts the nine specialists, by bare name");
        for (const t of ["agent", "ask_user", "todo"]) assert.ok((data["tools"] as string[]).includes(t), `conductor: ${t}`);
      } else {
        assert.deepEqual(data["agents"], [], fm.name);
        assert.equal(data["user-invocable"], false, fm.name);
        for (const t of ["agent", "ask_user"]) assert.ok(!(data["tools"] as string[]).includes(t), `${fm.name}: no ${t}`);
      }
    }
  });

  test(`inlined skills [${mode}]: each agent body ends with its source skills under "## Skill: <name>", in order`, () => {
    const files = fxDist(mode);
    for (const a of source.agents) {
      const { body } = front(text(files, agentFile(a.name)));
      let at = -1;
      for (const s of listField(a.data!["skills"])) {
        const i = body.indexOf(`\n${skillHeading(s)}\n`);
        assert.ok(i > at, `${a.name}: ${s} inlined after the previous skill`);
        at = i;
      }
    }
  });

  test(`C002-TC-310 (C002-TS-310) [${mode}]: install/mcp.json declares sdd-files and sdd-shell (stdio, sdd-mcp --profile …); no other file declares a server`, () => {
    const files = fxDist(mode);
    const servers = mcp(files).servers;
    assert.deepEqual(servers["sdd-files"], { args: ["--profile", "files"], command: "sdd-mcp", type: "stdio" });
    assert.deepEqual(servers["sdd-shell"], { args: ["--profile", "shell"], command: "sdd-mcp", type: "stdio" });
    for (const [n, s] of Object.entries(servers)) if (n !== "sdd-files" && n !== "sdd-shell") assert.notEqual(s.command, "sdd-mcp", n);
    for (const [n, s] of Object.entries(table.mcp_servers).filter(([, s]) => s.modes.includes(mode)))
      assert.deepEqual(servers[n], s.transport === "http" ? { type: "http", url: s.url } : { type: "stdio", command: s.command, args: s.args ?? [] }, n);
    for (const [p, b] of files) {
      if (p === CONFIG || !p.endsWith(".json")) continue;
      const doc = JSON.parse(b.toString("utf8")) as Record<string, unknown>;
      assert.ok(!("servers" in doc) && !("mcpServers" in doc), `${p} declares no MCP server`);
    }
    assert.ok(!files.has(".mcp.json"));
  });
}

test("C002-TC-124 (C002-TS-124), Copilot row: the serena entry of install/mcp.json runs sdd serena-launch --user-data --read-only -- start-mcp-server, then the table's Serena arguments", () => {
  for (const mode of MODES) {
    const serena = mcp(fxDist(mode)).servers["serena"]!;
    assert.equal(serena.type, "stdio");
    assert.equal(serena.command, "sdd");
    const args = serena.args!;
    assert.deepEqual(args.slice(0, 5), ["serena-launch", "--user-data", "--read-only", "--", "start-mcp-server"]);
    assert.deepEqual(args.slice(5), table.mcp_servers["serena"]!.args!.slice(5), "followed by the Serena arguments of the mapping table");
    const entry = JSON.stringify(serena);
    for (const banned of ["${CLAUDE_PLUGIN_ROOT}", "${CLAUDE_PLUGIN_DATA}", "SERENA_HOME"]) assert.ok(!entry.includes(banned), `no ${banned}`);
  }
});

test("C002-TC-305 (C002-TS-305): each of the 13 prompt files has agent sdd-conductor and no claude --agent guard line", () => {
  for (const mode of MODES) {
    const files = fxDist(mode);
    for (const name of commandNames) {
      const t = text(files, promptFile(name));
      const { data } = front(t);
      assert.equal(data["agent"], CONDUCTOR, name);
      assert.equal(typeof data["description"], "string");
      assert.ok(!t.includes("claude --agent architect:sdd-conductor"), `${name}: no guard line`);
      assert.ok(!/^This command runs in the `architect:sdd-conductor` main session\./m.test(t), name);
      const src = source.commands.find((c) => c.name === name)!.data!;
      if (typeof src["argument-hint"] === "string" && src["argument-hint"].trim() !== "") assert.equal(data["argument-hint"], src["argument-hint"], `${name}: argument-hint`);
    }
  }
});

test("C002-TC-328 (C002-TS-328): the prompt files are exactly <name>.prompt.md, new, init and doctor included", () => {
  const names = inDir(fxDist(table.enforcement_mode), PROMPTS_DIR).sort();
  assert.deepEqual(names, commandNames.map((n) => `${n}.prompt.md`).sort());
  for (const n of ["new.prompt.md", "init.prompt.md", "doctor.prompt.md"]) assert.ok(names.includes(n), n);
});

test("C002-TC-308 (C002-TS-308): under sdd MCP server enforcement every agent has a tools list and no agent or prompt file grants a generic edit or terminal tool", () => {
  const files = fxDist("sdd-mcp-server");
  for (const n of agentNames) {
    const tools = toolsOf(files, agentFile(n));
    for (const t of tools) assert.ok(!GENERIC.has(t), `${n}: grants ${t}`);
  }
  for (const n of commandNames) for (const t of toolsOf(files, promptFile(n))) assert.ok(!GENERIC.has(t), `${n}.prompt.md: grants ${t}`);
  const conductor = toolsOf(files, agentFile(CONDUCTOR));
  assert.ok(!conductor.includes("edit") && !conductor.includes("execute"), "the conductor grants neither edit nor execute");
});

test("C002-TC-339 (C002-TS-339): under the Copilot hooks fallback the conductor and every prompt file grant sdd-files/* and sdd-shell/* and no generic tool; the specialists hold the table's generic tools", () => {
  const files = fxDist("copilot-hooks");
  const holders = [agentFile(CONDUCTOR), ...commandNames.map(promptFile)];
  for (const p of holders) {
    const tools = toolsOf(files, p);
    for (const t of ["sdd-files/*", "sdd-shell/*"]) assert.ok(tools.includes(t), `${p}: ${t}`);
    for (const t of tools) assert.ok(!GENERIC.has(t), `${p}: grants ${t}`);
  }
  // The other side of C002-REQ-321: a specialist with Write or Bash gets the generic tools, not the profiles.
  const writer = toolsOf(files, agentFile("sdd-spec-writer"));
  for (const t of [...hooksGrants("Write"), ...hooksGrants("Bash")]) assert.ok(writer.includes(t), `sdd-spec-writer: ${t}`);
  assert.ok(!writer.includes("sdd-files/*") && !writer.includes("sdd-shell/*"));
});

test("C002-TC-306 (C002-TS-306): the install notes state prerequisites, the npm install, the install command, the settings after it, the Local session type, the server start and the subagent rule", () => {
  const notes = text(fxDist(table.enforcement_mode), INSTALL);
  const version = (JSON.parse(readFileSync(join(PLUGIN, ".claude-plugin", "plugin.json"), "utf8")) as { version: string }).version;
  assert.ok(source.files.some((f) => f.path === INSTALL_SOURCE), "the install-notes source is part of the source plugin");
  assert.ok(!notes.includes("{{"), "every token resolved");
  assert.match(notes, /Node\.js 20 or later/);
  const vscode = table.host.tested_versions["vscode"]!;
  const chat = table.host.tested_versions["copilot-chat"]!;
  assert.ok(notes.includes(`VS Code ${vscode} with GitHub Copilot Chat ${chat}, the`), "the tested versions of the table");
  // The doctor remedies table of the generated doctor prompt names the same tested versions.
  const doctor = text(fxDist(table.enforcement_mode), promptFile("doctor"));
  assert.ok(doctor.includes(`tested versions: VS Code ${vscode}, GitHub Copilot Chat ${chat}`), "doctor remedies: same versions");
  assert.match(notes, /Claude models of the three tiers \(Opus, Sonnet and Haiku\)/);
  assert.ok(notes.includes(`npm install -g architect-sdd@${version}`));
  const install = notes.indexOf("sdd install copilot --package <folder>");
  assert.ok(install > 0, "the install command");
  assert.match(notes, /In a terminal of your own \(not through an agent\)/);
  assert.match(notes, /again in each further repository, and\s+again after you move the package folder or replace it with another version/);
  for (const f of [".github/agents/", ".github/hooks/architect-guard.json", ".github/architect-install.json", ".vscode/mcp.json"]) assert.ok(notes.includes(f), f);
  assert.match(notes, /all of them in version control or none/);
  assert.match(notes, /denies every tool call in the\s+repository until/, "the fail-closed clone");
  for (const [setting, value] of [["chat.plugins.enabled", "`true`"], ["chat.pluginLocations", "the package folder"], ["chat.askQuestions.enabled", "`true`"]] as const) {
    const at = notes.indexOf(`\`${setting}\`: ${value}`);
    assert.ok(at > install, `${setting} with its value, after the install step`);
  }
  assert.match(notes, /reload the window/);
  assert.match(notes, /\*\*Local\*\* session type/);
  assert.match(notes, /select `sdd-conductor` as the session agent/);
  assert.match(notes, /workspace MCP servers .* start only\s+after the first message of a session/s);
  assert.match(notes, /In a repository that contains `\.sdd\/`, while hooks are enabled, every subagent that is not an\s+Architect agent \(a host built-in agent such as `general-purpose`, or one of your own agents started\s+as a subagent\) can call only the read-only tools of the tool classes file/);
  assert.match(notes, /sdd MCP server enforcement/, "the enforcement mode by its glossary name");
  // Order of C002-IF-005 §5: unpack, install, settings, session, servers, subagents.
  const order = ["Unpack this package", "sdd install copilot --package", "`chat.plugins.enabled`", "**Local**", "start only", "can call only the read-only"].map((s) => notes.indexOf(s));
  assert.deepEqual([...order].sort((a, b) => a - b), order, "steps in the order of C002-IF-005 §5");
  // C002-T-065 (defect D-019 item 1, critic CR-69): after the steps, exactly one Copilot CLI note.
  const cli = notes.split(/\n\s*\n/).filter((p) => /Copilot CLI/.test(p) && !/session type/.test(p));
  assert.equal(cli.length, 1, `one Copilot CLI note: ${JSON.stringify(cli)}`);
  const note = cli[0]!.replace(/\s+/g, " ");
  assert.ok(notes.indexOf(cli[0]!) > order[order.length - 1]!, "the note comes after the six steps");
  assert.match(note, /Copilot CLI is no supported host of this package/);
  assert.match(note, /`--agent architect:sdd-conductor`/);
  assert.match(note, /on its own default model/);
  assert.match(note, /the conductor runs on its tier only with `--model <model>`, where `<model>` is the `model` field of `agents\/sdd-conductor\.agent\.md`/);
  // The model field that the note points to, read from the generated agent file.
  const conductor = text(fxDist(table.enforcement_mode), "agents/sdd-conductor.agent.md");
  const model = /^model:\s*(\S+)\s*$/m.exec(conductor)?.[1];
  assert.ok(model && Object.values(table.models).includes(model), `the conductor's model field ${model} is a model of the table`);
  assert.ok(!notes.includes("GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS"), "the workspace-hooks variable is not named");
});

for (const row of ["agents/sdd-critic.agent.md", "scripts/sdd.mjs", "install/plugin.json", "install/mcp.json", "install/hooks.template.json", "hooks/tool-classes.json"]) {
  test(`C002-TC-302 (C002-TS-302): fx-dist-bad without ${row} is reported naming it`, () => {
    const mode = table.enforcement_mode;
    const bad = new Map(fxDist(mode));
    assert.ok(bad.delete(row), row);
    const findings = copilotPackageFindings(bad, emitInput(mode));
    assert.ok(findings.length > 0 && findings.every((f) => f.code === "TGT-LAYOUT-001"), JSON.stringify(findings));
    assert.ok(findings.some((f) => f.file === row && f.message.includes(row)), JSON.stringify(findings));
  });
}

test("C002-TS-301 root rule: a plugin.json, .mcp.json or hooks.json at the package root is reported naming it", () => {
  const mode = table.enforcement_mode;
  for (const p of ROOT_FORBIDDEN) {
    const bad = new Map(fxDist(mode));
    bad.set(p, Buffer.from("{}\n"));
    const findings = copilotPackageFindings(bad, emitInput(mode));
    assert.ok(findings.some((f) => f.code === "TGT-LAYOUT-001" && f.file === p && f.message.includes("package root")), `${p}: ${JSON.stringify(findings)}`);
  }
});

test("C002-TC-327 (C002-TS-327): sdd-files removed from install/mcp.json, or sdd-shell declared in a root .mcp.json, is reported (TGT-MCP-001)", () => {
  const mode = table.enforcement_mode;
  const removed = new Map(fxDist(mode));
  const doc = mcp(removed);
  delete doc.servers["sdd-files"];
  removed.set(CONFIG, Buffer.from(JSON.stringify(doc, null, 2) + "\n"));
  let found = copilotPackageFindings(removed, emitInput(mode)).filter((f) => f.code === "TGT-MCP-001");
  assert.equal(found.length, 1, JSON.stringify(found));
  assert.equal(found[0]!.file, "install/mcp.json");
  assert.ok(found[0]!.message.includes("install/mcp.json") && found[0]!.message.includes('"sdd-files"'), found[0]!.message);

  const planted = new Map(fxDist(mode));
  planted.set(".mcp.json", Buffer.from(JSON.stringify({ mcpServers: { "sdd-shell": { command: "sdd-mcp", args: ["--profile", "shell"] } } }) + "\n"));
  found = copilotPackageFindings(planted, emitInput(mode)).filter((f) => f.code === "TGT-MCP-001");
  assert.equal(found.length, 1, JSON.stringify(found));
  assert.equal(found[0]!.file, ".mcp.json");
  assert.ok(found[0]!.message.includes(".mcp.json") && found[0]!.message.includes('"sdd-shell"'), found[0]!.message);
});

test("a source plugin without its bundled CLI fails the Copilot generation (ERR-GEN-007), so no package lacks the CLI copy", () => {
  const { cli: _cli, ...rest } = source;
  const result = emitCopilot({ ...emitInput(table.enforcement_mode), source: rest });
  assert.equal(result.files.size, 0);
  assert.ok(result.diagnostics.some((d) => d.code === "ERR-GEN-007" && d.message.includes("scripts/sdd.mjs")), JSON.stringify(result.diagnostics));
});
